// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0); }
    function testRegression_property() public {
        address user = address(0x1234);
        address savings = address(0x5678);

        // Deploy mock savings contract that returns fixed credits
        vm.mockCall(
            savings,
            abi.encodeWithSelector(ISavingsContractV2.depositSavings.selector),
            abi.encode(100)
        );

        vm.prank(user);
        c.supplyTokenTo(1000, user);

        uint256 balance = c.balanceOfToken(user);
        assertTrue(balance > 0, "balanceOfToken should be non-zero after deposit");
    }
}

