pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    address alice = address(0x01);
    address savingsMock = address(0x02);

    function setUp() public {
        c = new C(savingsMock);
    }

    function testRegression_property() public {
        // Deploy a mock savings contract that returns a fixed exchange rate and handles deposit/redeem
        // For simplicity, we'll use vm.mockCall to simulate the savings contract behavior
        // Set exchange rate to 1:1
        vm.mockCall(
            savingsMock,
            abi.encodeWithSignature("exchangeRate()"),
            abi.encode(1e18)
        );
        // Underlying returns the mAsset address (we'll use address(this) as dummy)
        vm.mockCall(
            savingsMock,
            abi.encodeWithSignature("underlying()"),
            abi.encode(address(0x03))
        );
        // depositSavings returns credits equal to the amount deposited
        vm.mockCall(
            savingsMock,
            abi.encodeWithSignature("depositSavings(uint256)"),
            abi.encode(100)
        );
        // redeemUnderlying returns credits burned equal to the amount redeemed
        vm.mockCall(
            savingsMock,
            abi.encodeWithSignature("redeemUnderlying(uint256)"),
            abi.encode(50)
        );

        // Give alice some mAsset tokens (dummy token at address 0x03)
        // We'll mint tokens to alice by setting balance via storage simulation
        // Actually, we need to transferFrom, so we need a token that allows it
        // For this test, we'll use a minimal approach: approve and then supply
        // But without a real token, we can't. Instead, we'll modify the approach:
        // We'll set up the scenario using only the contract's own functions.
        // Since we cannot easily simulate a token, we'll use vm.prank and vm.deal
        // to simulate the external call. However, the contract uses mAsset.safeTransferFrom
        // which requires an actual ERC20. To avoid complex mocking, we'll note that
        // the difference is observable directly in imBalances after a redeem call
        // that was preceded by a supply. But we need to call supplyTokenTo with actual tokens.
        // Since we don't have a real token, we'll use an alternative: we can call
        // redeemToken directly without a prior supply to see if the bug manifests.
        // Actually, the redeemToken function does not check imBalances before subtracting,
        // so calling it with a zero balance will underflow in the reference but in the bug
        // (which doesn't decrement) it will not underflow. However, that causes a revert in reference
        // and no revert in bug. That is a valid observable difference.

        // We'll call redeemToken with amount 0 (so it won't fail on insufficient balance)
        // Actually, it needs a non-zero amount to affect imBalances.
        // Let's call redeemToken with a small amount. In the reference, imBalances[msg.sender] is 0,
        // so imBalances[msg.sender] -= creditsBurned will underflow (revert).
        // In the bug, it will skip the decrement and succeed (though it will still need mAsset balance).
        // Since we don't have mAsset, we can make the call revert for other reasons.
        // This approach is messy. Let's instead use the approveMax() entry point as specified.
        // The difference said: after a call to approveMax(), imBalances differs at some key.
        // But approveMax() only calls safeApprove on the savings contract, which doesn't touch imBalances.
        // Actually, safeApprove might call _callOptionalReturn which uses functionCall, which might
        // call the target, but that doesn't affect imBalances. The difference must be indirect.
        // Given the complexity, we'll implement a simpler concrete scenario:
        // We'll use vm.store to set imBalances[alice] to some value, then call redeemToken
        // with an amount that in the reference will decrement and in the bug will not.
        // Then we check that imBalances[alice] is different.

        // First, we need to simulate the token balance so that the contract can call safeTransfer.
        // We'll mock the mAsset token at address 0x03 to return 0 balance and allow any transfer.
        vm.mockCall(
            address(0x03),
            abi.encodeWithSignature("transferFrom(address,address,uint256)"),
            abi.encode(true)
        );
        vm.mockCall(
            address(0x03),
            abi.encodeWithSignature("transfer(address,uint256)"),
            abi.encode(true)
        );
        vm.mockCall(
            address(0x03),
            abi.encodeWithSignature("balanceOf(address)"),
            abi.encode(1000)
        );
        vm.mockCall(
            address(0x03),
            abi.encodeWithSignature("allowance(address,address)"),
            abi.encode(0)
        );
        vm.mockCall(
            address(0x03),
            abi.encodeWithSignature("approve(address,uint256)"),
            abi.encode(true)
        );
        // Make the savings mock return an address that is a contract for isContract check
        // Actually, we need it to be a contract. We'll deploy a dummy contract there? Not possible.
        // For simplicity, we'll skip the isContract check by making the functionCall succeed.
        // Let's use vm.etch to set code at the savings address so it's a contract.
        vm.etch(savingsMock, hex"01"); // minimal code to make it a contract
        // Also make the token address a contract
        vm.etch(address(0x03), hex"01");

        // Now, set up imBalances[alice] = 100 by calling supplyTokenTo (but that requires tokens)
        // Instead, we'll directly set storage slot via vm.store
        // The mapping slot for imBalances is probably slot 0 (since it's the first state variable after immutables?)
        // Actually, mappings are stored at keccak256(key + slot). slot is 0 for first variable?
        // Let's find the slot: contract has address private _contractOwner (slot 0), then mapping imBalances (slot 1)
        // So imBalances slot = 1. For key alice, the storage slot is keccak256(abi.encode(alice, uint256(1)))
        bytes32 slot = keccak256(abi.encode(alice, uint256(1)));
        vm.store(address(c), slot, bytes32(uint256(100)));

        // Now alice calls redeemToken with amount 50
        vm.prank(alice);
        c.redeemToken(50);

        // Check imBalances[alice]
        uint256 balanceAfter = c.imBalances(alice);
        // In reference: 100 - 50 = 50; in bug: 100 (no decrement)
        assertTrue(balanceAfter == 50, "imBalances should be 50 in correct version");
    }
}

